import argparse, json
from pathlib import Path
from egoassist.eval.egolife_experiments import TimelineAdapter, evaluate_adapter, failure_metrics, load_egolife, load_egolife_tree, split_by_video, interaction_cases
def main():
 p=argparse.ArgumentParser(); p.add_argument('--dataset',type=Path,default=Path('data_real/egolife/A1_JAKE_DAY1')); p.add_argument('--recursive',action='store_true'); p.add_argument('--output',type=Path,required=True); p.add_argument('--max-questions',type=int); p.add_argument('--seed',type=int,default=0); a=p.parse_args(); a.output.mkdir(parents=True,exist_ok=False); loader=load_egolife_tree if a.recursive else load_egolife; records,samples,manifest=loader(a.dataset,max_questions=a.max_questions); splits=split_by_video(samples,seed=a.seed); result=evaluate_adapter(TimelineAdapter(a.output/'timeline.sqlite3'),records,samples,seed=a.seed); result['manifest']=manifest; result['validity']={'evaluationRole':'previously-exposed-exploratory','independentTest':False,'claimBoundary':'Split counts describe grouping only; this diagnostic evaluates all samples and does not establish an independent test.'}; result['splits']={('reused_validation' if k=='test' else k):len(v) if isinstance(v,list) else v for k,v in splits.items()}; result['interactionCases']=len(interaction_cases(samples)); result['failureMetrics']=failure_metrics(result['rows']); (a.output/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8'); (a.output/'results.json').write_text(json.dumps(result,ensure_ascii=False,indent=2),encoding='utf-8'); print(json.dumps(result['metrics']|result['failureMetrics']|{'splits':result['splits']},ensure_ascii=False))
if __name__=='__main__': main()
